/** 터미널 제목에서 사람이 읽을 작업 이름만 남긴다. 하네스 기본 제목이면 null. */
export type TitleHarness = "claude" | "pi";

/** 스피너 글리프(`✳`, `⠂` 등)는 글자가 아니므로 앞에서 떼어 낸다. */
const leadingGlyphs = /^[^\p{L}\p{N}]+/u;

/** claude: `✳ Terminal blind overlay`. 기본 제목(`Claude Code`)과 빈 제목은 작업 이름이 아니다. */
function claudeTitle(title: string): string | null {
	const topic = title.replace(leadingGlyphs, "").trim();
	if (!topic) return null;
	if (/^claude(\s+code)?$/i.test(topic)) return null;
	return topic;
}

/** pi: `π - 작업 이름 - 폴더` 또는 `Pi-Bolt - 작업 이름 - 폴더`. 작업 이름은 양끝 사이 전부다. */
function piTitle(title: string): string | null {
	const parts = title.split(" - ").map((part) => part.trim());
	if (parts.length < 3) return null;
	const topic = parts.slice(1, -1).join(" - ").trim();
	return topic || null;
}

/** 탭에 보일 작업 이름. 하네스가 붙인 기본 제목뿐이면 null. */
export function taskTitle(harness: TitleHarness, title: string): string | null {
	if (!title.trim()) return null;
	return harness === "claude" ? claudeTitle(title) : piTitle(title);
}

